create or replace function public.admin_issue_penalty(p_amount numeric,p_player_id uuid,p_reason text,p_title text) returns jsonb language plpgsql security definer set search_path=public as $$ begin if not public.is_bank_admin() then raise exception 'Недостаточно прав'; end if; if coalesce(p_amount,0)<=0 then raise exception 'Сумма штрафа должна быть больше нуля'; end if; if not exists(select 1 from public.profiles where id=p_player_id) then raise exception 'Игрок не найден'; end if; insert into public.fines(user_id,amount,title,reason,created_at) values(p_player_id,p_amount,coalesce(nullif(trim(p_title),''),'Штраф'),coalesce(nullif(trim(p_reason),''),'Штраф'),now()); return jsonb_build_object('success',true); end; $$;
grant execute on function public.admin_issue_penalty(numeric,uuid,text,text) to authenticated;

create or replace function public.admin_balance_operation(p_amount numeric,p_description text,p_player_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare old_balance numeric; new_balance numeric; begin if not public.is_bank_admin() then raise exception 'Недостаточно прав'; end if; if p_amount is null or p_amount=0 then raise exception 'Сумма не может быть нулевой'; end if; select coalesce(balance,0) into old_balance from public.profiles where id=p_player_id for update; if not found then raise exception 'Игрок не найден'; end if; new_balance:=old_balance+p_amount; if new_balance<0 then raise exception 'Недостаточно средств'; end if; update public.profiles set balance=new_balance where id=p_player_id; insert into public.transactions(from_user,to_user,amount,type,description,created_at) values(case when p_amount<0 then p_player_id else auth.uid() end,case when p_amount>0 then p_player_id else auth.uid() end,abs(p_amount),case when p_amount>0 then 'deposit' else 'withdraw' end,coalesce(nullif(trim(p_description),''),case when p_amount>0 then 'Пополнение администратором' else 'Снятие администратором' end),now()); return jsonb_build_object('success',true,'old_balance',old_balance,'new_balance',new_balance); end; $$;
grant execute on function public.admin_balance_operation(numeric,text,uuid) to authenticated;

create or replace function public.bank_create_notification(p_user_id uuid,p_title text,p_message text,p_kind text default 'info') returns jsonb language plpgsql security definer set search_path=public as $$ begin if not public.is_bank_admin() then raise exception 'Недостаточно прав'; end if; if not exists(select 1 from public.profiles where id=p_user_id) then raise exception 'Игрок не найден'; end if; insert into public.bank_notifications(user_id,title,message,kind,created_at) values(p_user_id,coalesce(nullif(trim(p_title),''),'Сообщение банка'),p_message,coalesce(nullif(trim(p_kind),''),'info'),now()); return jsonb_build_object('success',true); end; $$;
grant execute on function public.bank_create_notification(uuid,text,text,text) to authenticated;

alter table public.transactions add column if not exists created_at timestamptz not null default now();
create table if not exists public.bank_notifications(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,title text not null,message text not null,kind text not null default 'info',is_read boolean not null default false,created_at timestamptz not null default now());
alter table public.bank_notifications enable row level security;
drop policy if exists "players read own bank notifications" on public.bank_notifications;
create policy "players read own bank notifications" on public.bank_notifications for select to authenticated using(user_id=auth.uid());
notify pgrst,'reload schema';
